var subagentTimelineRowSchema = z2.object({ type: z2.string(), text: z2.string().optional(), timestamp: z2.string().optional() });
var tasksSubagentTimelineRpc = defineRpc2({
  name: "tasks.subagent-timeline",
  input: z2.object({
    parentAgentId: z2.string().min(1),
    subagentId: z2.string().min(1),
    direction: z2.enum(["after", "tail"]),
    limit: z2.number().int().positive().max(100)
  }),
  output: z2.object({ rows: z2.array(subagentTimelineRowSchema), error: z2.string().nullable() })
});
var tasksUnarchiveRpc = defineRpc2({
  name: "tasks.unarchive",
  input: z2.object({ agentId: z2.string().min(1) }),
  output: z2.object({ ok: z2.boolean(), error: z2.string().nullable() })
});
var tasksRenameRpc = defineRpc2({
  name: "tasks.rename",
  input: z2.object({ agentId: z2.string().min(1), title: z2.string().trim().min(1) }),
  output: z2.object({ ok: z2.boolean(), error: z2.string().nullable() })
});
var sessionTokensSchema = z2.object({
  /** Every token the session used: input, cache writes and reads, output. */
  total: z2.number(),
  /** The part read from the provider's prompt cache. */
  cached: z2.number()
});
var tasksSessionTokensRpc = defineRpc2({
  name: "tasks.session-tokens",
  input: z2.object({ agentId: z2.string().min(1) }),
  output: z2.object({ tokens: sessionTokensSchema.nullable() })
});
var tasksChunkRpc = defineRpc2({
  name: "tasks.chunk",
  input: z2.object({ id: z2.string().min(1) }),
  output: z2.object({ code: z2.string().nullable() })
});
var tasksLabelsRpc = defineRpc2({
  name: "tasks.labels",
  input: z2.object({}),
  output: z2.object({ labels: z2.array(z2.object({ name: z2.string(), color: z2.string() })).nullable() })
});
var tasksBotDefinitionSchema = z2.object({
  id: z2.string(),
  name: z2.string(),
  color: z2.string(),
  archived: z2.boolean()
});
var tasksBotsRpc = defineRpc2({
  name: "tasks.bots",
  input: z2.object({}),
  output: z2.object({ bots: z2.array(tasksBotDefinitionSchema) })
});
var tasksProjectIconsRpc = defineRpc2({
  name: "tasks.project-icons",
  input: z2.object({ projectIds: z2.array(z2.string().min(1)).min(1).max(200) }),
  output: z2.object({
    icons: z2.array(
      z2.object({
        projectId: z2.string(),
        // `color`: the icon's theme colour (`#rrggbb`) for the subtask mark, null when it cannot be read.
        icon: z2.object({ data: z2.string(), mimeType: z2.string(), color: z2.string().nullable().optional() }).nullable()
      })
    ).nullable()
  })
});

// shared/model-catalog.ts
import { z as z3 } from "zod";
var modelCatalogSchema = z3.object({
  providers: z3.array(z3.string()),
  providerLabels: z3.record(z3.string(), z3.string()).default({}),
  models: z3.array(z3.object({
    id: z3.string(),
    label: z3.string(),
    thinkingOptions: z3.array(z3.object({ id: z3.string(), label: z3.string() })),
    defaultThinkingOptionId: z3.string().nullable()
  })),
  error: z3.string().nullable()
});
function thinkingForModel(model, current3) {
  const options2 = model?.thinkingOptions ?? [];
  if (current3 && options2.some((option) => option.id === current3)) return current3;
  return ["off", "none", "disabled", "minimal", "low", "medium", "high", "xhigh", "max", "ultra", "ultracode"].find((id) => options2.some((option) => option.id === id)) ?? options2[0]?.id ?? "";
}
function modelSelection(model, current3) {
  return { model: model?.id ?? "", thinkingOptionId: thinkingForModel(model, current3) };
}

// shared/title-generation.ts
import { defineRpc as defineRpc3, defineSettings } from "@getpaseo/plugin";
import { z as z4 } from "zod";
var TITLE_HELPER_LABEL = "better-paseo.purpose";
var TITLE_HELPER_PURPOSE = "title-generation";
var DEFAULT_TITLE_PROMPT = "Generate a concise, specific task title from the supplied conversation. Use the language of the first user message. Focus on the actual goal and preserve key module names, issue numbers, and technical identifiers. Limit the title to 60 characters including spaces. Return only the title, without quotes, explanations, or Markdown.";
var titleGenerationSettingsSchema = z4.object({
  /** Generate from the first prompt at turn start; retain the stored settings key. */
  afterFirstReply: z4.boolean().catch(false),
  customModel: z4.boolean().catch(false),
  disableThinking: z4.boolean().catch(true),
  provider: z4.string().catch(""),
  model: z4.string().catch(""),
  thinkingOptionId: z4.string().catch(""),
  prompt: z4.string().trim().min(1).max(8e3).catch(DEFAULT_TITLE_PROMPT)
});
var TITLE_GENERATION_SETTINGS = defineSettings({
  id: "title-generation",
  scope: "host",
  version: 1,
  schema: titleGenerationSettingsSchema
});
var titleUpdateStateSchema = z4.discriminatedUnion("state", [
  z4.object({ state: z4.literal("idle") }),
  // The title streams in as `text`; `helperId` is the helper agent whose live timeline announces each chunk.
  z4.object({ state: z4.literal("running"), text: z4.string().optional(), helperId: z4.string().optional() }),
  z4.object({ state: z4.literal("done"), title: z4.string(), previousTitle: z4.string().optional() }),
  z4.object({ state: z4.literal("error"), error: z4.string() })
]);
var titleUpdateRpc = defineRpc3({
  name: "tasks.title-update",
  input: z4.object({ agentId: z4.string().min(1), action: z4.enum(["start", "status"]), mode: z4.enum(["apply", "preview"]).default("apply") }),
  output: titleUpdateStateSchema
});
var titleUndoRpc = defineRpc3({
  name: "tasks.title-undo",
  input: z4.object({ agentId: z4.string().min(1), title: z4.string().min(1), previousTitle: z4.string().trim().min(1) }),
  output: z4.object({ ok: z4.boolean(), error: z4.string().nullable() })
});
var titleLanguageRpc = defineRpc3({
  name: "tasks.title-language",
  input: z4.object({ language: z4.enum(["en", "zh"]) }),
  output: z4.object({ ok: z4.literal(true) })
});
var titleModelsRpc = defineRpc3({
  name: "tasks.title-models",
  input: z4.object({ provider: z4.string() }),
  output: modelCatalogSchema
});

